from collections import Counter

def comps_of(g, col):
    h, w = len(g), len(g[0])
    cells = {(r, c) for r in range(h) for c in range(w) if g[r][c] == col}
    out = []
    while cells:
        c = cells.pop(); comp = [c]; st = [c]
        while st:
